package com.cirro.android;

import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.Build;
import android.provider.Settings;
import androidx.core.content.FileProvider;
import androidx.core.app.NotificationCompat;
import androidx.core.app.NotificationManagerCompat;
import com.getcapacitor.*;
import com.getcapacitor.annotation.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

@CapacitorPlugin(name="AndroidUpdates")
public class AndroidUpdatesPlugin extends Plugin {
 private static final String REPO="arunabhajana/Cirro";
 private static final long MAX_APK=512L*1024*1024;
 private static final AtomicBoolean cancelled=new AtomicBoolean(false),downloading=new AtomicBoolean(false);
 private static volatile HttpURLConnection active;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 static void cancelCurrent(){cancelled.set(true);HttpURLConnection connection=active;if(connection!=null)connection.disconnect();}
 private android.content.SharedPreferences prefs(){return getContext().getSharedPreferences("cirro-updates",Context.MODE_PRIVATE);}
 @SuppressWarnings("deprecation") private PackageInfo installed()throws Exception{return getContext().getPackageManager().getPackageInfo(getContext().getPackageName(),Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES);}
 @SuppressWarnings("deprecation") private long code(PackageInfo info){return Build.VERSION.SDK_INT>=28?info.getLongVersionCode():info.versionCode;}
 private int compare(String a,String b){String[] x=a.replaceFirst("^v","").split("\\."),y=b.replaceFirst("^v","").split("\\.");for(int i=0;i<3;i++){int aa=i<x.length?Integer.parseInt(x[i]):0,bb=i<y.length?Integer.parseInt(y[i]):0;if(aa!=bb)return Integer.compare(aa,bb);}return 0;}
 private void allowed(URL url,boolean initial)throws Exception{String host=url.getHost();if(!"https".equals(url.getProtocol())||(url.getPort()!=-1&&url.getPort()!=443))throw new IOException("Updates require a secure download URL.");if(initial){if(!"github.com".equals(host)||!url.getPath().startsWith("/"+REPO+"/releases/download/"))throw new IOException("This update did not come from Cirro’s release repository.");}else if(!"github.com".equals(host)&&!"release-assets.githubusercontent.com".equals(host)&&!"objects.githubusercontent.com".equals(host)&&!"api.github.com".equals(host))throw new IOException("Unexpected update download host.");}
 private HttpURLConnection open(String address,boolean download)throws Exception{URL url=new URL(address);if(download)allowed(url,true);else if(!address.startsWith("https://api.github.com/repos/"+REPO+"/releases"))throw new IOException("Invalid update feed.");for(int redirect=0;redirect<6;redirect++){allowed(url,false);HttpURLConnection connection=(HttpURLConnection)url.openConnection();active=connection;connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(30000);connection.setRequestProperty("Accept",download?"application/octet-stream":"application/vnd.github+json");connection.setRequestProperty("User-Agent","Cirro-Android-Updater");int status=connection.getResponseCode();if(status>=300&&status<400){String next=connection.getHeaderField("Location");connection.disconnect();if(next==null)throw new IOException("The update server returned an invalid redirect.");url=new URL(url,next);continue;}return connection;}throw new IOException("Too many update redirects.");}
 private String read(InputStream stream,int maximum)throws Exception{try(InputStream input=stream;ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int count;while((count=input.read(bytes))!=-1){if(output.size()+count>maximum)throw new IOException("The release information is too large.");output.write(bytes,0,count);}return output.toString("UTF-8");}}
 @PluginMethod public void info(PluginCall call){try{PackageInfo info=installed();JSObject result=new JSObject().put("version",info.versionName).put("versionCode",code(info)).put("wasUpdated",info.lastUpdateTime-info.firstInstallTime>1000).put("openUpdates",getActivity().getIntent().getBooleanExtra("cirro_updates",false));getActivity().getIntent().removeExtra("cirro_updates");String ready=prefs().getString("ready",null);if(ready!=null){JSONObject release=new JSONObject(ready);File apk=apk(release);if(apk.exists()&&compare(release.getString("version"),info.versionName)>0)result.put("ready",JSObject.fromJSONObject(release));else{apk.delete();prefs().edit().remove("ready").apply();}}call.resolve(result);}catch(Exception error){call.reject("Could not read the installed app version.");}}
 @PluginMethod public void check(PluginCall call){worker.execute(()->{HttpURLConnection connection=null;try{PackageInfo current=installed();connection=open("https://api.github.com/repos/"+REPO+"/releases?per_page=20",false);int status=connection.getResponseCode();if(status==404){call.resolve(new JSObject().put("available",false).put("published",false));return;}if(status!=200)throw new IOException(status==403?"GitHub’s update limit was reached. Please try again later.":"Could not check updates. Try again when you’re online.");JSONArray releases=new JSONArray(read(connection.getInputStream(),2*1024*1024));JSONObject latest=null;for(int i=0;i<releases.length();i++){JSONObject release=releases.getJSONObject(i);if(release.optBoolean("draft")||release.optBoolean("prerelease"))continue;String version=release.optString("tag_name").replaceFirst("^v","");if(!version.matches("\\d+\\.\\d+\\.\\d+"))continue;JSONArray assets=release.optJSONArray("assets");if(assets==null)continue;for(int j=0;j<assets.length();j++){JSONObject asset=assets.getJSONObject(j);if(!"Cirro-android.apk".equals(asset.optString("name")))continue;String digest=asset.optString("digest");long size=asset.optLong("size");if(!digest.matches("sha256:[a-fA-F0-9]{64}")||size<=0||size>MAX_APK)continue;URL address=new URL(asset.getString("browser_download_url"));allowed(address,true);if(latest==null||compare(version,latest.getString("version"))>0)latest=new JSONObject().put("version",version).put("url",address.toString()).put("sha256",digest.substring(7).toLowerCase(Locale.ROOT)).put("size",size).put("notes",release.optString("body","").substring(0,Math.min(6000,release.optString("body","").length())));}}
 if(latest==null){call.resolve(new JSObject().put("available",false).put("published",false));return;}boolean newer=compare(latest.getString("version"),current.versionName)>0;call.resolve(new JSObject().put("available",newer).put("published",true).put("release",JSObject.fromJSONObject(latest)));}catch(Exception error){call.reject(error.getMessage()==null?"Update check failed.":error.getMessage());}finally{if(connection!=null)connection.disconnect();active=null;}});}
 private File apk(JSONObject release)throws Exception{String hash=release.getString("sha256");if(!hash.matches("[a-f0-9]{64}"))throw new IOException("Invalid update checksum.");File directory=new File(getContext().getFilesDir(),"updates");if(!directory.exists()&&!directory.mkdirs())throw new IOException("Could not create update storage.");return new File(directory,hash+".apk");}
 private String hash(File file)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream input=new FileInputStream(file)){byte[] data=new byte[65536];int count;while((count=input.read(data))!=-1)digest.update(data,0,count);}StringBuilder value=new StringBuilder();for(byte b:digest.digest())value.append(String.format("%02x",b));return value.toString();}
 @SuppressWarnings("deprecation") private Set<String> signers(PackageInfo info)throws Exception{Signature[] signatures=Build.VERSION.SDK_INT>=28?(info.signingInfo==null?new Signature[0]:info.signingInfo.getApkContentsSigners()):info.signatures;Set<String> result=new HashSet<>();if(signatures!=null)for(Signature signature:signatures)result.add(android.util.Base64.encodeToString(signature.toByteArray(),android.util.Base64.NO_WRAP));return result;}
 @SuppressWarnings("deprecation") private void verify(File file,JSONObject release)throws Exception{if(file.length()!=release.getLong("size")||!hash(file).equals(release.getString("sha256")))throw new IOException("This download could not be verified. Please download it again.");PackageInfo current=installed(),candidate=getContext().getPackageManager().getPackageArchiveInfo(file.getAbsolutePath(),Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES);if(candidate==null||!getContext().getPackageName().equals(candidate.packageName))throw new IOException("The download is not a Cirro Android app.");if(!release.getString("version").equals(candidate.versionName)||code(candidate)<=code(current))throw new IOException("This APK is not a newer build of Cirro.");Set<String> expected=signers(current),actual=signers(candidate);if(expected.isEmpty()||!expected.equals(actual))throw new IOException("This update uses a different signing key. It cannot replace this installation.");}
 private void progress(long done,long total,String phase){notifyListeners("progress",new JSObject().put("bytes",done).put("total",total).put("phase",phase));if(NotificationManagerCompat.from(getContext()).areNotificationsEnabled())try{NotificationManagerCompat.from(getContext()).notify(UpdateDownloadService.ID,UpdateDownloadService.notification(getContext(),phase+" · "+Math.round(done*100.0/Math.max(1,total))+"%",(int)(done*100/Math.max(1,total))));}catch(Exception ignored){}}
 @PluginMethod public void download(PluginCall call){JSObject details=call.getObject("release");if(details==null){call.reject("Update details are missing.");return;}if(!downloading.compareAndSet(false,true)){call.reject("An update is already downloading.");return;}cancelled.set(false);try{Intent service=new Intent(getContext(),UpdateDownloadService.class);if(Build.VERSION.SDK_INT>=26)getContext().startForegroundService(service);else getContext().startService(service);}catch(Exception error){downloading.set(false);call.reject("Keep Cirro open to start the update download.");return;}worker.execute(()->{File part=null;HttpURLConnection connection=null;try{JSONObject release=new JSONObject(details.toString());File target=apk(release);long expected=release.getLong("size");if(expected<=0||expected>MAX_APK)throw new IOException("The update exceeds the supported download size.");part=new File(target.getAbsolutePath()+".part");connection=open(release.getString("url"),true);if(connection.getResponseCode()!=200)throw new IOException("The update download failed. Please try again.");long announced=connection.getContentLengthLong();if(announced>0&&announced!=expected)throw new IOException("The update size changed. Check for updates again.");long received=0,last=0;try(InputStream input=connection.getInputStream();OutputStream output=new FileOutputStream(part)){byte[] data=new byte[65536];int count;while((count=input.read(data))!=-1){if(cancelled.get())throw new IOException("Update download cancelled.");received+=count;if(received>expected||received>MAX_APK)throw new IOException("The update is larger than expected.");output.write(data,0,count);if(System.currentTimeMillis()-last>150){progress(received,expected,"Downloading");last=System.currentTimeMillis();}}}if(cancelled.get())throw new IOException("Update download cancelled.");progress(expected,expected,"Verifying");verify(part,release);if(target.exists()&&!target.delete())throw new IOException("Could not replace the previous download.");if(!part.renameTo(target))throw new IOException("Could not save the verified update.");part=null;prefs().edit().putString("ready",release.toString()).apply();call.resolve(new JSObject().put("ready",true));}catch(Exception error){call.reject(error.getMessage()==null?"Update download failed.":error.getMessage(),cancelled.get()?"UPDATE_CANCELLED":"UPDATE_FAILED");}finally{if(part!=null)part.delete();if(connection!=null)connection.disconnect();active=null;downloading.set(false);getContext().stopService(new Intent(getContext(),UpdateDownloadService.class));}});}
 @PluginMethod public void cancel(PluginCall call){cancelCurrent();call.resolve();}
 @PluginMethod public void install(PluginCall call){worker.execute(()->{try{String stored=prefs().getString("ready",null);if(stored==null)throw new IOException("Download the update first.");JSONObject release=new JSONObject(stored);File file=apk(release);verify(file,release);getActivity().runOnUiThread(()->{try{if(Build.VERSION.SDK_INT>=26&&!getContext().getPackageManager().canRequestPackageInstalls()){getActivity().startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getContext().getPackageName())));call.resolve(new JSObject().put("needsPermission",true));return;}Uri uri=FileProvider.getUriForFile(getContext(),getContext().getPackageName()+".fileprovider",file);Intent install=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);getActivity().startActivity(install);call.resolve(new JSObject().put("needsPermission",false));}catch(Exception error){call.reject("Android could not open the installer.");}});}catch(Exception error){call.reject(error.getMessage()==null?"The downloaded update is no longer available.":error.getMessage());}});}
}
